let t = $json.candidates[0].content.parts[0].text.replace(/```json|```/g,'').trim();
let r; try { r = JSON.parse(t); } catch(e) { r = { intent:'other', sentiment:0, reply:'Namaste! Thank you for your message — our team will reply shortly. 🙏' }; }
const src = $('Webhook: message in').item.json.body || {};
const escalate = r.sentiment <= -0.3 || r.intent === 'complaint';
return [{ json: { Time: new Date().toISOString(), Channel: src.channel||'web', From: src.from||src.name||'', Message: src.message||'', Intent: r.intent, Sentiment: r.sentiment, Reply: r.reply, Escalated: escalate ? 'yes':'no', escalate } }];

